// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    ReentrancyDAO c;
    function setUp() public { c = new ReentrancyDAO(); }
    function testFuzz_property(uint256 amount, address caller) public {
        vm.assume(amount > 0);
        vm.assume(caller != address(0));
        vm.assume(caller != address(c));

        Attacker attacker = new Attacker(c);
        vm.deal(address(attacker), amount);
        attacker.depositAndWithdraw(amount);

        uint256 balanceAfterFirst = address(c).balance;
        attacker.depositAndWithdraw(amount);
        uint256 balanceAfterSecond = address(c).balance;

        assertTrue(balanceAfterSecond == balanceAfterFirst);
    }
}

contract Attacker {
    ReentrancyDAO c;
    bool private reentering;
    uint256 private reenterAmount;

    constructor(ReentrancyDAO _c) { c = _c; }

    function depositAndWithdraw(uint256 amount) external payable {
        reenterAmount = amount;
        c.deposit{value: amount}();
        c.withdrawAll();
    }

    receive() external payable {
        if (reenterAmount > 0 && !reentering) {
            reentering = true;
            uint256 amt = reenterAmount;
            reenterAmount = 0;
            c.deposit{value: amt}();
            c.withdrawAll();
            reentering = false;
        }
    }
}
